                rf"\s*&?\s*([A-Za-z_]\w*)"
                rf"\s*:\s*{re.escape(array_name)}\s*\)"
                rf"[\s\S]{{0,250}}?"
                rf"(?:std::)?cin\s*>>\s*\1",
