            r"(?:std::)?vector\s*<\s*"
            r"(int|long\s+long|long|float|double)"
            r"\s*>\s*"
            r"([A-Za-z_]\w*)\s*\(\s*\1\s*\)"
            r"[\s\S]{0,1000}?"
            r"(?:std::)?cin\s*>>\s*"
            r"([A-Za-z_]\w*)\s*;"
            r"[\s\S]{0,500}?"
            r"(?:while|for)\s*\("
            r"[\s\S]{0,250}?"
            r"(?:std::)?cin\s*>>\s*"
            r"([A-Za-z_]\w*)\s*>>\s*"
            r"([A-Za-z_]\w*)",
